import threading

class BulkheadFullError(Exception):
    """Raised when a tenant's bulkhead has no remaining capacity or queue slots."""
    pass

class TenantBulkhead:
    """Tenant-aware bulkhead that limits concurrent executions and queued work per tenant.

    The implementation enforces:
    * Strict type and value validation for constructor arguments and method inputs.
    * Isolation of state per tenant so that one tenant's saturation does not affect others.
    * Correct accounting of active and queued tasks with atomic updates.
    * Safe rollback of counters even when the wrapped function raises.
    """

    def __init__(self, max_concurrent: int = 2, max_queue_size: int = 2):
        # Validate numeric parameters – reject bools and non‑positive values.
        if type(max_concurrent) is not int or max_concurrent <= 0:
            raise ValueError("max_concurrent must be a positive int (bool not allowed)")
        if type(max_queue_size) is not int or max_queue_size < 0:
            raise ValueError("max_queue_size must be a non‑negative int (bool not allowed)")

        self.max_concurrent = max_concurrent
        self.max_queue_size = max_queue_size
        self._lock = threading.Lock()
        # Mapping tenant_id -> {'active': int, 'queue': int}
        self._tenant_state: dict[str, dict[str, int]] = {}

    def _validate_tenant_id(self, tenant_id):
        if not isinstance(tenant_id, str) or tenant_id == "":
            raise ValueError("tenant_id must be a non‑empty string")
        # Explicitly reject bools (bool is subclass of int but not a valid ID)
        if isinstance(tenant_id, bool):
            raise ValueError("tenant_id must be a string, not a bool")

    def _validate_callable(self, func):
        if not callable(func):
            raise ValueError("func must be callable")

    def execute(self, tenant_id, func, *args, **kwargs):
        """Execute *func* under the bulkhead constraints for *tenant_id*.

        If the tenant already has ``max_concurrent`` active executions, the call is
        placed in a bounded queue. If the queue is full, ``BulkheadFullError`` is
        raised. The function is executed immediately after the accounting update;
        the queue count is merely a limit, not a waiting mechanism.
        """
        # Parameter validation – defensive programming.
        self._validate_tenant_id(tenant_id)
        self._validate_callable(func)

        # Determine whether we increment the active or queue counter.
        mode = None  # will be set to 'active' or 'queue'
        with self._lock:
            state = self._tenant_state.setdefault(tenant_id, {"active": 0, "queue": 0})
            if state["active"] < self.max_concurrent:
                state["active"] += 1
                mode = "active"
            elif state["queue"] < self.max_queue_size:
                state["queue"] += 1
                mode = "queue"
            else:
                # No capacity left for this tenant.
                raise BulkheadFullError("Bulkhead capacity reached for tenant '{}".format(tenant_id))

        try:
            return func(*args, **kwargs)
        finally:
            # Ensure counters are rolled back even if func raises.
            with self._lock:
                state = self._tenant_state.get(tenant_id)
                if state:
                    if mode == "active" and state["active"] > 0:
                        state["active"] -= 1
                    elif mode == "queue" and state["queue"] > 0:
                        state["queue"] -= 1
                    # Clean up empty tenant entries to avoid unbounded growth.
                    if state["active"] == 0 and state["queue"] == 0:
                        del self._tenant_state[tenant_id]

